    ext:{ nome:'Ministério da Saúde, Diretrizes Brasileiras para o Diagnóstico e Tratamento de Intoxicações Agudas por Agrotóxicos (2020)', url:'https://registro.sp.gov.br/cerest/arquivos/biblioteca/106/2020-5813824172-intoxicacoes-agudas-agrotoxicos-11-2020-isbn.pdf', trecho:'considere a administração de uma única dose de carvão ativado em pacientes atendidos em até 60 minutos da exposição, com histórico de ingestão de grandes quantidades de agrotóxicos e que sejam adsorvidos por esse composto.' },
